begin;
truncate public.couples,public.profiles,public.operation_receipts cascade;
set local search_path=public,extensions;select no_plan();
insert into auth.users(id,email,email_confirmed_at) values('00000000-0000-4000-8000-000000000073','notify-first@example.test',now()),('00000000-0000-4000-8000-000000000074','notify-partner@example.test',now());
insert into public.profiles(user_id,display_name) values('00000000-0000-4000-8000-000000000073','First'),('00000000-0000-4000-8000-000000000074','Partner');
insert into public.couples(id,name,start_date) values('10000000-0000-4000-8000-000000000073','Test','2024-01-01');
insert into public.memberships(couple_id,user_id,slot) values('10000000-0000-4000-8000-000000000073','00000000-0000-4000-8000-000000000073',1),('10000000-0000-4000-8000-000000000073','00000000-0000-4000-8000-000000000074',2);
select private.emit_change('10000000-0000-4000-8000-000000000073','00000000-0000-4000-8000-000000000073',gen_random_uuid(),'upload','create','30000000-0000-4000-8000-000000000073');
insert into public.upload_batches(id,couple_id,owner_id,event_id,recipient_id,success_count,failure_count) select '30000000-0000-4000-8000-000000000073',couple_id,actor_id,id,'00000000-0000-4000-8000-000000000074',1,2 from public.change_events;
select is((select count(*)::integer from public.notifications),1,'Exactly one partner notification');
select is((select state from public.deliveries),'disabled','Email disabled by default');
set local role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000073',true);
select is((select count(*)::integer from public.notification_inbox()),0,'Actor cannot inspect partner inbox');
reset role;
set local role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000074',true);
select is((select count(*)::integer from public.notification_inbox()),1,'Recipient can read inbox');
select is((select upload_summary->>'success_count' from public.notification_inbox()),'1','Safe batch summary projected');
select is((select count(*)::integer from jsonb_object_keys((select upload_summary from public.notification_inbox()))),4,'Only four batch summary fields exposed');
select is((select delivery_state from public.notification_inbox()),'disabled','External disabled state visible');
select ok(not has_table_privilege('authenticated','public.upload_batches','SELECT'),'No raw batch read grant');
select ok(not has_table_privilege('authenticated','public.deliveries','SELECT'),'No raw delivery read grant');
reset role;
select public.commit_mutation('00000000-0000-4000-8000-000000000074','notification.mark_read',jsonb_build_object('notification_id',(select id from public.notifications)),gen_random_uuid(),'read',now()+interval '1 day');
select ok((select read_at is not null from public.notifications),'Read state persisted');
select is((select count(*)::integer from public.change_events),1,'Mark-read cannot recursively notify');
select throws_ok($$select public.commit_mutation('00000000-0000-4000-8000-000000000073','notification.mark_read',jsonb_build_object('notification_id',(select id from public.notifications)),gen_random_uuid(),'bad',now()+interval '1 day')$$,'P0001','ACCESS_DENIED','Actor cannot alter recipient read state');
update public.upload_batches set success_count=2,failure_count=1;
set local role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000074',true);
select is((select upload_summary->>'success_count' from public.notification_inbox()),'2','Later batch summary updates same notification');
select ok((select read_at is not null from public.notification_inbox()),'Summary update preserves read state');
select is((select count(*)::integer from public.notification_inbox(target=>'90000000-0000-4000-8000-000000000073')),0,'Changed notification reference is uniformly absent');
reset role;
update public.upload_batches set recipient_id='00000000-0000-4000-8000-000000000073';
set local role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000074',true);
select ok((select upload_summary is null from public.notification_inbox()),'Wrong batch recipient join cannot leak summary');
reset role;
set local role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000075',true);
select is((select count(*)::integer from public.notification_inbox()),0,'Outsider denied');
reset role;
select ok(not has_function_privilege('anon','public.notification_inbox(integer,timestamp with time zone,uuid,uuid)','EXECUTE'),'Anonymous denied');
select public.commit_mutation('00000000-0000-4000-8000-000000000074','notification.preferences','{"email_enabled":true,"expected_version":0}',gen_random_uuid(),'pref',now()+interval '1 day');
select is((select count(*)::integer from public.notifications),1,'Preference updates do not replay or notify');
select is((select state from public.deliveries),'disabled','Enabling preference does not replay history');
update private.notification_config set email_enabled=true;
update private.usage_budget set email_attempts=0,day=null where scope='email';
select private.emit_change('10000000-0000-4000-8000-000000000073','00000000-0000-4000-8000-000000000073',gen_random_uuid(),'memory','create',gen_random_uuid()) from generate_series(1,21);
create temporary table lease_claim as select public.claim_email(true) jobs;
select is(jsonb_array_length((select jobs from lease_claim)),20,'Worker claims at most twenty');
select is(jsonb_array_length(public.claim_email(true)),1,'Second claim cannot duplicate active leases');
select is((select email_attempts from private.usage_budget where scope='email'),21,'Every claimed attempt reserves daily budget');
update public.deliveries set first_attempt_at=now()-interval '31 minutes',lease_until=now()-interval '1 second' where state='leased';
select is(jsonb_array_length(public.claim_email(true)),0,'Expired provider dedupe never resends');
select is((select count(*)::integer from public.deliveries where error_code='DEDUPE_EXPIRED'),20,'Expired first claim quarantined');
select is(jsonb_array_length(public.claim_email(true)),0,'Second sweep quarantines remaining expired lease');
select is((select count(*)::integer from public.deliveries where error_code='DEDUPE_EXPIRED'),21,'All uncertain expired claims quarantined');
select private.emit_change('10000000-0000-4000-8000-000000000073','00000000-0000-4000-8000-000000000073',gen_random_uuid(),'memory','create',gen_random_uuid());
update public.deliveries set state='leased',attempts=5,lease_until=now()-interval '1 second' where state='pending';
select public.claim_email(true);
select is((select count(*)::integer from public.deliveries where error_code='ATTEMPTS_EXHAUSTED'),1,'Crashed fifth attempt cannot become a sixth send');
select ok(not has_function_privilege('authenticated','public.claim_email(boolean)','EXECUTE'),'Browser cannot claim email jobs');
select ok(not has_table_privilege('authenticated','private.notification_config','SELECT'),'Browser cannot read global email configuration');
select * from finish();rollback;
